import { ChevronLeftIcon, ChevronRightIcon } from 'lucide-react'
import * as React from 'react'
import { Button } from '@/components/ui/button'

interface TableFooterProps {
  rowCount: number
  showPagination: boolean
  pageIndex: number
  pageCount: number
  canPreviousPage: boolean
  canNextPage: boolean
  onPreviousPage: () => void
  onNextPage: () => void
  onShiftTabToTable: () => void
}

export const TableFooter = React.forwardRef<HTMLDivElement, TableFooterProps>(
  function TableFooter(
    { rowCount, showPagination, pageIndex, pageCount, canPreviousPage, canNextPage, onPreviousPage, onNextPage, onShiftTabToTable },
    ref
  ) {
    return (
      <div
        ref={ref}
        className="flex items-center justify-between"
        onKeyDown={(e) => {
          if (e.key === 'Tab' && e.shiftKey && rowCount > 0) {
            const focusables = Array.from(
              (ref as React.RefObject<HTMLDivElement>).current?.querySelectorAll<HTMLElement>('button:not([disabled]),[tabindex="0"]') ?? []
            )
            if (focusables[0] === document.activeElement) {
              e.preventDefault()
              e.stopPropagation()
              onShiftTabToTable()
            }
          }
        }}
      >
        <p className="text-xs text-muted-foreground">
          {rowCount} row{rowCount !== 1 ? 's' : ''}
        </p>
        {showPagination && (
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground">
              Page {pageIndex + 1} of {Math.max(pageCount, 1)}
            </span>
            <Button
              variant="outline"
              size="icon"
              className="h-7 w-7"
              onClick={onPreviousPage}
              disabled={!canPreviousPage}
            >
              <ChevronLeftIcon className="h-3.5 w-3.5" />
              <span className="sr-only">Previous page</span>
            </Button>
            <Button
              variant="outline"
              size="icon"
              className="h-7 w-7"
              onClick={onNextPage}
              disabled={!canNextPage}
            >
              <ChevronRightIcon className="h-3.5 w-3.5" />
              <span className="sr-only">Next page</span>
            </Button>
          </div>
        )}
      </div>
    )
  }
)

import * as React from 'react'
import { cn } from '@/lib/utils'

interface RowCheckboxProps {
  checked: boolean
  indeterminate?: boolean
  onChange?: (e: React.ChangeEvent<HTMLInputElement>) => void
  onClick?: (e: React.MouseEvent<HTMLInputElement>) => void
  className?: string
}

export function RowCheckbox({ checked, indeterminate, onChange, onClick, className }: RowCheckboxProps) {
  const ref = React.useRef<HTMLInputElement>(null)
  React.useEffect(() => {
    if (ref.current) ref.current.indeterminate = !!indeterminate
  }, [indeterminate])
  const active = checked || indeterminate
  return (
    <span
      className={cn('inline-flex items-center justify-center cursor-pointer group', className)}
      onClick={onClick}
    >
      <input ref={ref} type="checkbox" checked={checked} onChange={onChange} tabIndex={-1} className="sr-only" />
      <span
        className={cn(
          'h-3.5 w-3.5 rounded-xs border flex items-center justify-center transition-colors',
          active
            ? 'bg-selected border-selected'
            : 'border-foreground/35 group-hover:border-selected'
        )}
      >
        {indeterminate && (
          <span className="block h-px w-2 bg-selected-foreground" />
        )}
        {checked && !indeterminate && (
          <svg viewBox="0 0 10 8" className="h-2 w-2.5 fill-none stroke-selected-foreground stroke-[2]">
            <polyline points="1,4 4,7 9,1" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        )}
      </span>
    </span>
  )
}

import { ChevronRightIcon } from 'lucide-react'
import * as React from 'react'
import {
  CommandDialog,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from '@/components/ui/command'
import { cn } from '@/lib/utils'
import type { RowAction } from './types'

interface ActionsDialogProps<TData> {
  open: boolean
  onOpenChange: (open: boolean) => void
  rowActions: RowAction<TData>[]
  actionPage: RowAction<TData> | null
  onSetActionPage: (page: RowAction<TData> | null) => void
  effectiveRows: TData[]
  actionsHeading: string
}

export function ActionsDialog<TData>({
  open,
  onOpenChange,
  rowActions,
  actionPage,
  onSetActionPage,
  effectiveRows,
  actionsHeading,
}: ActionsDialogProps<TData>) {
  return (
    <CommandDialog
      open={open}
      onOpenChange={onOpenChange}
      commandKey={actionPage?.label ?? 'root'}
      title="Row Actions"
      description="Choose an action to apply to selected rows"
    >
      <CommandInput
        autoFocus
        placeholder={actionPage ? `Search ${actionPage.label.toLowerCase()}...` : 'Type a command or search...'}
        onKeyDown={(e) => {
          if (e.key === 'Backspace' && (e.target as HTMLInputElement).value === '') {
            onSetActionPage(null)
          }
        }}
      />
      <CommandList>
        <CommandEmpty>No actions available.</CommandEmpty>
        {actionPage ? (
          <CommandGroup heading={
            <span className="flex items-center justify-between w-full">
              <span>{actionPage.label}</span>
              <span className="font-normal text-muted-foreground">{actionsHeading}</span>
            </span>
          }>
            {actionPage.subActions!.map((sub, i) => (
              <CommandItem
                key={i}
                onSelect={() => {
                  sub.onClick?.(effectiveRows)
                  onOpenChange(false)
                  onSetActionPage(null)
                }}
                className={cn(sub.destructive && 'text-destructive')}
              >
                {sub.icon}
                <span className="flex-1">{sub.label}</span>
                {sub.shortcut && (
                  <span className="flex items-center gap-0.5">
                    {sub.shortcut.split('').map((ch, j) => (
                      <kbd key={j} className="rounded border border-border bg-muted px-1 py-0.5 font-mono text-[10px] leading-none text-muted-foreground">{ch}</kbd>
                    ))}
                  </span>
                )}
              </CommandItem>
            ))}
          </CommandGroup>
        ) : (
          <CommandGroup heading={actionsHeading}>
            {rowActions.map((action, i) => (
              <CommandItem
                key={i}
                onSelect={() => {
                  if (action.subActions?.length) {
                    onSetActionPage(action)
                  } else {
                    action.onClick?.(effectiveRows)
                    onOpenChange(false)
                  }
                }}
                className={cn(action.destructive && 'text-destructive')}
              >
                {action.icon}
                <span className="flex-1">{action.label}</span>
                {action.shortcut && (
                  <kbd className="rounded border border-border bg-muted px-1 py-0.5 font-mono text-[10px] leading-none text-muted-foreground">
                    {action.shortcut}
                  </kbd>
                )}
                {action.subActions?.length ? (
                  <ChevronRightIcon className="h-3.5 w-3.5 text-muted-foreground" />
                ) : null}
              </CommandItem>
            ))}
          </CommandGroup>
        )}
      </CommandList>
    </CommandDialog>
  )
}

import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { type Row, flexRender } from '@tanstack/react-table'
import { GripVerticalIcon } from 'lucide-react'
import * as React from 'react'
import { cn } from '@/lib/utils'
import type { SortableRowProps } from './SortableRow'

export function ListRow<TData>({
  row,
  displayIndex,
  activeRowIndex,
  activeRowSource,
  reorderable,
  customTranslateY,
  isDragGroup,
  justDropped,
  onMeasureHeight,
  onRowClick,
  onRowMouseEnter,
  onContextMenu,
}: SortableRowProps<TData>) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: row.id,
    disabled: !reorderable,
  })

  const nodeRef = React.useCallback((node: HTMLDivElement | null) => {
    setNodeRef(node)
    if (node && onMeasureHeight) onMeasureHeight(node.offsetHeight)
  }, [setNodeRef, onMeasureHeight])

  const isSelected = row.getIsSelected()
  const isActive = activeRowIndex === displayIndex

  const style: React.CSSProperties =
    customTranslateY !== null
      ? { transform: `translateY(${customTranslateY}px)`, transition: 'none' }
      : justDropped
        ? { transform: 'none', transition: 'none' }
        : { transform: CSS.Transform.toString(transform), transition }

  return (
    <div
      ref={nodeRef}
      style={style}
      data-display-index={displayIndex}
      data-state={isSelected ? 'selected' : undefined}
      className={cn(
        'flex items-center gap-2 px-2 py-1.5 border-b border-border/40 cursor-pointer select-none text-sm',
        'data-[state=selected]:bg-selected/10 hover:data-[state=selected]:bg-selected/15 hover:bg-muted/25',
        isActive && activeRowSource === 'keyboard' && 'row-ring',
        (isDragging || isDragGroup) && 'shadow-sm bg-background relative z-10',
      )}
      onClick={() => onRowClick(displayIndex)}
      onMouseEnter={() => onRowMouseEnter(displayIndex)}
      onContextMenu={(e) => onContextMenu(e, displayIndex)}
    >
      {row.getVisibleCells().map((cell) => {
        const meta = cell.column.columnDef.meta as Record<string, unknown> | undefined
        const grow = meta?.grow === true

        if (cell.column.id === '_reorder') {
          return (
            <span
              key={cell.id}
              {...attributes}
              {...listeners}
              tabIndex={-1}
              className="flex items-center shrink-0 text-muted-foreground/30 hover:text-muted-foreground/70 cursor-grab active:cursor-grabbing outline-none"
            >
              <GripVerticalIcon className="h-3.5 w-3.5" />
            </span>
          )
        }

        if (cell.column.id === '_select') {
          return (
            <span
              key={cell.id}
              className={cn(
                'flex items-center shrink-0',
                !isSelected && activeRowIndex !== displayIndex && 'opacity-0',
              )}
            >
              {flexRender(cell.column.columnDef.cell, cell.getContext())}
            </span>
          )
        }

        const size = cell.column.columnDef.size
        return (
          <div
            key={cell.id}
            className={cn(
              grow ? 'flex-1 min-w-0 truncate' : 'shrink-0',
            )}
            style={!grow && size ? { width: size } : undefined}
          >
            {flexRender(cell.column.columnDef.cell, cell.getContext())}
          </div>
        )
      })}
    </div>
  )
}

import { ChevronRightIcon } from 'lucide-react'
import * as React from 'react'
import { createPortal } from 'react-dom'
import { cn } from '@/lib/utils'
import type { RowAction } from './types'

interface ContextMenuProps<TData> {
  contextMenu: { x: number; y: number; rowIndex: number } | null
  contextSub: { action: RowAction<TData>; x: number; y: number } | null
  rowActions: RowAction<TData>[]
  onSetContextSub: (sub: { action: RowAction<TData>; x: number; y: number } | null) => void
  onClose: () => void
  getContextRows: () => TData[]
}

export function ContextMenu<TData>({
  contextMenu,
  contextSub,
  rowActions,
  onSetContextSub,
  onClose,
  getContextRows,
}: ContextMenuProps<TData>) {
  if (!contextMenu) return null
  return createPortal(
    <>
      <div
        style={{ top: contextMenu.y, left: contextMenu.x }}
        className="fixed z-50 min-w-[160px] overflow-hidden rounded-md border border-border bg-popover shadow-md py-1 [&_svg]:size-4 dark:text-primary"
        onClick={(e) => e.stopPropagation()}
      >
        {rowActions.map((action, i) => (
          <button
            key={i}
            className={cn(
              'flex w-full items-center gap-2 px-3 py-1.5 text-xs hover:bg-accent transition-colors text-left outline-none focus:bg-accent',
              action.destructive && 'text-destructive hover:text-destructive focus:text-destructive',
              contextSub?.action === action && 'bg-accent'
            )}
            onMouseEnter={(e) => {
              if (action.subActions?.length) {
                const rect = (e.currentTarget as HTMLElement).getBoundingClientRect()
                onSetContextSub({ action, x: rect.right + 4, y: rect.top })
              } else {
                onSetContextSub(null)
              }
            }}
            onClick={() => {
              if (!action.subActions?.length) {
                action.onClick?.(getContextRows())
                onClose()
              }
            }}
          >
            {action.icon}
            <span className="flex-1">{action.label}</span>
            {action.shortcut && (
              <kbd className="rounded border border-border bg-muted px-1 py-0.5 font-mono text-[10px] leading-none text-muted-foreground">
                {action.shortcut}
              </kbd>
            )}
            {action.subActions?.length ? <ChevronRightIcon className="h-3 w-3 opacity-50" /> : null}
          </button>
        ))}
      </div>
      {contextSub && (
        <div
          style={{ top: contextSub.y, left: contextSub.x }}
          className="fixed z-50 min-w-[140px] overflow-hidden rounded-md border border-border bg-popover shadow-md py-1 [&_svg]:size-4 dark:text-primary"
          onClick={(e) => e.stopPropagation()}
        >
          {contextSub.action.subActions!.map((sub, i) => (
            <button
              key={i}
              className={cn(
                'flex w-full items-center gap-2 px-3 py-1.5 text-xs hover:bg-accent transition-colors text-left outline-none focus:bg-accent',
                sub.destructive && 'text-destructive hover:text-destructive focus:text-destructive'
              )}
              onClick={() => {
                sub.onClick?.(getContextRows())
                onClose()
              }}
            >
              {sub.icon}
              <span className="flex-1">{sub.label}</span>
              {sub.shortcut && (
                <span className="flex items-center gap-0.5">
                  {sub.shortcut.split('').map((ch, j) => (
                    <kbd key={j} className="rounded border border-border bg-muted px-1 py-0.5 font-mono text-[10px] leading-none text-muted-foreground">{ch}</kbd>
                  ))}
                </span>
              )}
            </button>
          ))}
        </div>
      )}
    </>,
    document.body
  )
}

import {
  KeyboardSensor,
  PointerSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
  type DragMoveEvent,
  type DragStartEvent,
} from '@dnd-kit/core'
import { arrayMove, sortableKeyboardCoordinates } from '@dnd-kit/sortable'
import type { Row, Table } from '@tanstack/react-table'
import * as React from 'react'

interface UseDragParams<TData> {
  rows: Row<TData>[]
  selectedCount: number
  orderedData: TData[]
  setOrderedData: React.Dispatch<React.SetStateAction<TData[]>>
  onRowReorder?: (newData: TData[]) => void
  activeRowIndex: number | null
  setActiveRowIndex: React.Dispatch<React.SetStateAction<number | null>>
  getItemId: (row: TData) => string
  table: Table<TData>
  rowHeightRef: React.MutableRefObject<number>
}

export function useDrag<TData>({
  rows,
  selectedCount,
  orderedData,
  setOrderedData,
  onRowReorder,
  activeRowIndex,
  setActiveRowIndex,
  getItemId,
  table,
  rowHeightRef,
}: UseDragParams<TData>) {
  const [dragActiveId, setDragActiveId] = React.useState<string | null>(null)
  const [multiDragActive, setMultiDragActive] = React.useState(false)
  const [dragDeltaY, setDragDeltaY] = React.useState(0)
  const dragDeltaYRef = React.useRef(0)
  const [justDropped, setJustDropped] = React.useState(false)
  const justDroppedRafRef = React.useRef<number | null>(null)

  React.useEffect(() => () => {
    if (justDroppedRafRef.current) cancelAnimationFrame(justDroppedRafRef.current)
  }, [])

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  )

  const updateActiveRowAfterReorder = React.useCallback((newData: TData[]) => {
    if (activeRowIndex === null) return
    const activeRowId = rows[activeRowIndex]?.id
    if (!activeRowId) return
    const { pageIndex: pi, pageSize: ps } = table.getState().pagination
    const pageStart = pi * ps
    const newIdx = newData.findIndex(item => getItemId(item) === activeRowId) - pageStart
    setActiveRowIndex(newIdx >= 0 ? newIdx : null)
  }, [activeRowIndex, rows, table, getItemId, setActiveRowIndex])

  const handleDragStart = (event: DragStartEvent) => {
    const id = String(event.active.id)
    setDragActiveId(id)
    setDragDeltaY(0)
    dragDeltaYRef.current = 0
    const draggedRow = rows.find((r) => r.id === id)
    setMultiDragActive((draggedRow?.getIsSelected() ?? false) && selectedCount > 1)
  }

  const handleDragMove = (event: DragMoveEvent) => {
    if (multiDragActive) {
      dragDeltaYRef.current = event.delta.y
      setDragDeltaY(event.delta.y)
    }
  }

  const handleDragEnd = (event: DragEndEvent) => {
    const { active, over } = event
    const finalDeltaY = dragDeltaYRef.current
    setDragActiveId(null)
    setMultiDragActive(false)
    setDragDeltaY(0)
    dragDeltaYRef.current = 0

    const draggedRow = rows.find((r) => r.id === active.id)
    const isDraggedSelected = draggedRow?.getIsSelected() ?? false

    if (isDraggedSelected && selectedCount > 1) {
      const rowH = rowHeightRef.current
      const activeDomIndex = rows.findIndex((r) => r.id === active.id)
      const nonSelectedDomIndices = rows.map((r, i) => !r.getIsSelected() ? i : -1).filter(i => i !== -1)
      const insertAt_original = nonSelectedDomIndices.filter(i => i < activeDomIndex).length
      const insertAt = Math.max(0, Math.min(
        Math.round(insertAt_original + finalDeltaY / rowH),
        nonSelectedDomIndices.length
      ))
      const selectedIdSet = new Set(table.getSelectedRowModel().rows.map((r) => r.id))
      const selectedItems = orderedData.filter((item) => selectedIdSet.has(getItemId(item)))
      const unselectedItems = orderedData.filter((item) => !selectedIdSet.has(getItemId(item)))
      const newData = [
        ...unselectedItems.slice(0, insertAt),
        ...selectedItems,
        ...unselectedItems.slice(insertAt),
      ]
      setJustDropped(true)
      if (justDroppedRafRef.current) cancelAnimationFrame(justDroppedRafRef.current)
      justDroppedRafRef.current = requestAnimationFrame(() => {
        justDroppedRafRef.current = requestAnimationFrame(() => {
          setJustDropped(false)
        })
      })
      updateActiveRowAfterReorder(newData)
      setOrderedData(newData)
      onRowReorder?.(newData)
    } else {
      if (!over || active.id === over.id) return
      const oldIndex = orderedData.findIndex((item) => getItemId(item) === active.id)
      const newIndex = orderedData.findIndex((item) => getItemId(item) === over.id)
      if (oldIndex === -1 || newIndex === -1) return
      const newData = arrayMove(orderedData, oldIndex, newIndex)
      updateActiveRowAfterReorder(newData)
      setOrderedData(newData)
      onRowReorder?.(newData)
    }
  }

  let customTransforms: number[] | null = null
  if (multiDragActive && dragActiveId) {
    const rowH = rowHeightRef.current
    const activeDomIndex = rows.findIndex((r) => r.id === dragActiveId)
    if (activeDomIndex !== -1) {
      const selectedDomIndices = rows.map((r, i) => r.getIsSelected() ? i : -1).filter(i => i !== -1)
      const nonSelectedDomIndices = rows.map((r, i) => !r.getIsSelected() ? i : -1).filter(i => i !== -1)
      const groupSize = selectedDomIndices.length
      const insertAt_original = nonSelectedDomIndices.filter(i => i < activeDomIndex).length
      const insertAt_float = insertAt_original + dragDeltaY / rowH
      const insertAt = Math.max(0, Math.min(Math.round(insertAt_float), nonSelectedDomIndices.length))
      customTransforms = rows.map((row, domIndex) => {
        if (row.getIsSelected()) {
          const groupIdx = selectedDomIndices.indexOf(domIndex)
          const clamped = Math.max(0, Math.min(insertAt_float, nonSelectedDomIndices.length))
          return (clamped + groupIdx - domIndex) * rowH
        }
        const k = nonSelectedDomIndices.indexOf(domIndex)
        const target = k < insertAt ? k : k + groupSize
        return (target - domIndex) * rowH
      })
    }
  }

  return {
    sensors,
    dragActiveId,
    multiDragActive,
    justDropped,
    customTransforms,
    handleDragStart,
    handleDragMove,
    handleDragEnd,
  }
}

import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import { type Row, flexRender } from '@tanstack/react-table'
import { GripVerticalIcon } from 'lucide-react'
import * as React from 'react'
import { TableCell, TableRow } from '@/components/ui/table'
import { cn } from '@/lib/utils'

export interface SortableRowProps<TData> {
  row: Row<TData>
  displayIndex: number
  activeRowIndex: number | null
  activeRowSource: 'keyboard' | 'mouse'
  reorderable: boolean
  customTranslateY: number | null
  isDragGroup: boolean
  justDropped: boolean
  onMeasureHeight?: (height: number) => void
  onRowClick: (index: number) => void
  onRowMouseEnter: (index: number) => void
  onContextMenu: (e: React.MouseEvent, index: number) => void
}

export function SortableRow<TData>({
  row,
  displayIndex,
  activeRowIndex,
  activeRowSource,
  reorderable,
  customTranslateY,
  isDragGroup,
  justDropped,
  onMeasureHeight,
  onRowClick,
  onRowMouseEnter,
  onContextMenu,
}: SortableRowProps<TData>) {
  const { attributes, listeners, setNodeRef, transform, transition, isDragging } = useSortable({
    id: row.id,
    disabled: !reorderable,
  })

  const nodeRef = React.useCallback((node: HTMLTableRowElement | null) => {
    setNodeRef(node)
    if (node && onMeasureHeight) onMeasureHeight(node.offsetHeight)
  }, [setNodeRef, onMeasureHeight])

  const isSelected = row.getIsSelected()
  const isActive = activeRowIndex === displayIndex

  return (
    <TableRow
      ref={nodeRef}
      style={
        customTranslateY !== null
          ? { transform: `translateY(${customTranslateY}px)`, transition: 'none' }
          : justDropped
            ? { transform: 'none', transition: 'none' }
            : { transform: CSS.Transform.toString(transform), transition }
      }
      data-display-index={displayIndex}
      data-state={isSelected ? 'selected' : undefined}
      className={cn(
        'h-6 cursor-pointer select-none',
        'data-[state=selected]:bg-selected/10 hover:data-[state=selected]:bg-selected/15 hover:bg-muted/25',
        isActive && activeRowSource === 'keyboard' && 'row-ring',
        (isDragging || isDragGroup) && 'shadow-sm bg-background relative z-10',
      )}
      onClick={() => onRowClick(displayIndex)}
      onMouseEnter={() => onRowMouseEnter(displayIndex)}
      onContextMenu={(e) => onContextMenu(e, displayIndex)}
    >
      {row.getVisibleCells().map((cell) => (
        <TableCell
          key={cell.id}
          className={cn(
            'py-1.5 text-sm',
            (cell.column.id === '_select' || cell.column.id === '_reorder') && 'w-6 !pl-2 !pr-0'
          )}
        >
          {cell.column.id === '_reorder' ? (
            <span
              {...attributes}
              {...listeners}
              tabIndex={-1}
              className="flex items-center text-muted-foreground/30 hover:text-muted-foreground/70 cursor-grab active:cursor-grabbing outline-none"
            >
              <GripVerticalIcon className="h-3.5 w-3.5" />
            </span>
          ) : cell.column.id === '_select' ? (
            <span className={cn('flex items-center', !isSelected && activeRowIndex !== displayIndex && 'opacity-0')}>
              {flexRender(cell.column.columnDef.cell, cell.getContext())}
            </span>
          ) : (
            flexRender(cell.column.columnDef.cell, cell.getContext())
          )}
        </TableCell>
      ))}
    </TableRow>
  )
}

import {
  DndContext,
  closestCenter,
} from '@dnd-kit/core'
import { restrictToParentElement, restrictToVerticalAxis } from '@dnd-kit/modifiers'
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable'
import {
  type ColumnDef,
  type ColumnFiltersState,
  type RowSelectionState,
  type SortingState,
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  useReactTable,
} from '@tanstack/react-table'
import { ArrowUpDownIcon } from 'lucide-react'
import * as React from 'react'
import { Input } from '@/components/ui/input'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/components/ui/tooltip'
import { cn } from '@/lib/utils'
import { ContextMenu } from './ContextMenu'
import { ListRow } from './ListRow'
import { RowCheckbox } from './RowCheckbox'
import { SelectionBar } from './SelectionBar'
import { SortableRow } from './SortableRow'
import type { DataTableProps, RowAction } from './types'
import { ActionsDialog } from './ActionsDialog'
import { TableFooter } from './TableFooter'
import { useDrag } from './useDrag'
import { useKeyboardHandler } from './useKeyboardHandler'

export type { DataTableProps, RowAction }
export type { ShortcutKeys } from './types'

export function DataTable<TData, TValue>({
  columns,
  data,
  searchColumn,
  searchPlaceholder = 'Search...',
  rowActions,
  getRowLabel,
  pageSize = 10,
  onRowReorder,
  getRowId,
  view = 'table',
}: DataTableProps<TData, TValue>) {
  const showAll = pageSize === 'all'
  const [sorting, setSorting] = React.useState<SortingState>([])
  const [columnFilters, setColumnFilters] = React.useState<ColumnFiltersState>([])
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({})
  const [activeRowIndex, setActiveRowIndex] = React.useState<number | null>(null)
  const [activeRowSource, setActiveRowSource] = React.useState<'keyboard' | 'mouse'>('mouse')
  const beforeSentinelRef = React.useRef<HTMLDivElement>(null)
  const paginationRef = React.useRef<HTMLDivElement>(null)
  const tableContainerRef = React.useRef<HTMLDivElement>(null)
  const rowHeightRef = React.useRef<number>(33)
  const [contextMenu, setContextMenu] = React.useState<{
    x: number
    y: number
    rowIndex: number
  } | null>(null)
  const [contextSub, setContextSub] = React.useState<{
    action: RowAction<TData>
    x: number
    y: number
  } | null>(null)
  const [actionsOpen, setActionsOpen] = React.useState(false)
  const [actionPage, setActionPage] = React.useState<RowAction<TData> | null>(null)
  const [orderedData, setOrderedData] = React.useState<TData[]>(data)
  const suppressMouseRef = React.useRef(false)

  // Sync internal order when data changes externally (filter, server refresh, etc.)
  // Also follow the active row to its new position by tracking its stable ID.
  // rows/activeRowIndex are intentionally captured at the moment data changes (old ordering).
  // eslint-disable-next-line react-hooks/exhaustive-deps
  React.useEffect(() => {
    if (activeRowIndex !== null) {
      const activeId = rows[activeRowIndex]?.id
      if (activeId) {
        const idFn = getRowId ?? getStableId
        const newIdx = data.findIndex((item) => idFn(item) === activeId)
        setActiveRowIndex(newIdx >= 0 ? newIdx : null)
      }
    }
    setOrderedData(data)
  }, [data])

  // Stable ID per data object regardless of position — required for dnd-kit to track
  // items correctly across reorders (tanstack table's default IDs are position-based)
  const stableIdMap = React.useRef(new WeakMap<object, string>())
  const stableIdCounter = React.useRef(0)
  const getStableId = React.useCallback((row: TData): string => {
    if (typeof row !== 'object' || row === null) return String(stableIdCounter.current++)
    const obj = row as object
    if (!stableIdMap.current.has(obj)) {
      stableIdMap.current.set(obj, String(stableIdCounter.current++))
    }
    return stableIdMap.current.get(obj)!
  }, [])

  // Reset sub-page after the close animation finishes, not during, to avoid flashes
  React.useEffect(() => {
    if (!actionsOpen) {
      const t = setTimeout(() => setActionPage(null), 200)
      return () => clearTimeout(t)
    }
  }, [actionsOpen])

  const selectionColumn = React.useMemo<ColumnDef<TData, unknown>>(
    () => ({
      id: '_select',
      header: () => null,
      cell: ({ row }) => (
        <Tooltip>
          <TooltipTrigger asChild>
            <span className="inline-flex items-center">
              <RowCheckbox
                checked={row.getIsSelected()}
                onChange={row.getToggleSelectedHandler() as React.ChangeEventHandler<HTMLInputElement>}
                onClick={(e) => { e.stopPropagation(); row.toggleSelected() }}
              />
            </span>
          </TooltipTrigger>
          <TooltipContent className="flex items-center gap-1.5">
            Select row
            <kbd className="rounded border border-selected/30 bg-selected/10 px-1 py-0.5 font-mono text-[10px] leading-none">x</kbd>
          </TooltipContent>
        </Tooltip>
      ),
      enableSorting: false,
      enableColumnFilter: false,
      size: 16,
    }),
    [getRowLabel]
  )

  const reorderColumn = React.useMemo<ColumnDef<TData, unknown>>(
    () => ({
      id: '_reorder',
      header: () => null,
      cell: () => null, // rendered inside SortableRow directly
      enableSorting: false,
      enableColumnFilter: false,
      size: 16,
    }),
    []
  )

  const allColumns = React.useMemo<ColumnDef<TData, unknown>[]>(
    () => [
      ...(onRowReorder ? [reorderColumn] : []),
      selectionColumn,
      ...(columns as ColumnDef<TData, unknown>[]),
    ],
    [reorderColumn, selectionColumn, columns, onRowReorder]
  )

  const table = useReactTable({
    data: orderedData,
    columns: allColumns,
    getRowId: getRowId ?? getStableId,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    onSortingChange: setSorting,
    onColumnFiltersChange: setColumnFilters,
    onRowSelectionChange: setRowSelection,
    enableRowSelection: true,
    initialState: {
      pagination: { pageSize: showAll ? Number.MAX_SAFE_INTEGER : pageSize },
    },
    state: {
      sorting,
      columnFilters,
      rowSelection,
    },
  })

  const rows = table.getRowModel().rows
  const selectedRows = table.getSelectedRowModel().rows.map((r) => r.original)
  const selectedCount = selectedRows.length

  // Rows that actions apply to: explicit selection, or the keyboard-navigated row as implicit target
  const effectiveRows: TData[] =
    selectedCount > 0
      ? selectedRows
      : activeRowIndex !== null && rows[activeRowIndex]
        ? [rows[activeRowIndex].original]
        : []

  const actionsHeading = (() => {
    if (effectiveRows.length === 0) return 'Actions'
    if (effectiveRows.length === 1)
      return getRowLabel ? getRowLabel(effectiveRows[0]) : '1 row'
    return `${effectiveRows.length} rows`
  })()

  const {
    sensors,
    dragActiveId,
    multiDragActive,
    justDropped,
    customTransforms,
    handleDragStart,
    handleDragMove,
    handleDragEnd,
  } = useDrag({
    rows,
    selectedCount,
    orderedData,
    setOrderedData,
    onRowReorder,
    activeRowIndex,
    setActiveRowIndex,
    getItemId: getRowId ?? getStableId,
    table,
    rowHeightRef,
  })

  useKeyboardHandler({
    rowActions,
    rows,
    activeRowIndex,
    selectedCount,
    contextMenu,
    table,
    effectiveRows,
    setActionsOpen,
    setActionPage,
    setActiveRowIndex,
    setActiveRowSource,
    suppressMouseRef,
    setContextMenu,
  })

  React.useEffect(() => {
    const handler = () => { suppressMouseRef.current = false }
    window.addEventListener('mousemove', handler)
    return () => window.removeEventListener('mousemove', handler)
  }, [])

  React.useEffect(() => {
    if (activeRowIndex === null) return
    const el = tableContainerRef.current?.querySelector<HTMLElement>(`[data-display-index="${activeRowIndex}"]`)
    el?.scrollIntoView({ block: 'nearest', behavior: 'instant' })
  }, [activeRowIndex])

  // Close context menu on outside interaction
  React.useEffect(() => {
    if (!contextMenu) { setContextSub(null); return }
    const close = () => { setContextMenu(null); setContextSub(null) }
    window.addEventListener('click', close)
    window.addEventListener('scroll', close, true)
    return () => {
      window.removeEventListener('click', close)
      window.removeEventListener('scroll', close, true)
    }
  }, [contextMenu])

  const handleContextMenu = (e: React.MouseEvent, rowIndex: number) => {
    if (!rowActions?.length) return
    e.preventDefault()
    setActiveRowIndex(rowIndex)
    setContextMenu({ x: e.clientX, y: e.clientY, rowIndex })
  }

  // Actions apply to: context menu row (if not in selection), otherwise all selected
  const getContextRows = (): TData[] => {
    if (contextMenu === null) return selectedRows
    const contextRow = rows[contextMenu.rowIndex]
    if (!contextRow) return selectedRows
    if (selectedRows.length > 0 && contextRow.getIsSelected()) return selectedRows
    return [contextRow.original]
  }

  const pageIndex = table.getState().pagination.pageIndex
  const pageCount = table.getPageCount()

  const rowIds = rows.map((r) => r.id)

  return (
    <TooltipProvider>
    <div className="flex flex-col gap-3">
      {searchColumn && (
        <div className="flex items-center">
          <Input
            placeholder={searchPlaceholder}
            value={(table.getColumn(searchColumn)?.getFilterValue() as string) ?? ''}
            onChange={(e) =>
              table.getColumn(searchColumn)?.setFilterValue(e.target.value)
            }
            className="max-w-sm h-8 text-sm"
          />
        </div>
      )}

      <div
        ref={beforeSentinelRef}
        tabIndex={0}
        className="sr-only"
        onFocus={(e) => {
          if (rows.length === 0) return
          if (paginationRef.current?.contains(e.relatedTarget as Node)) return
          setActiveRowIndex(0)
          setActiveRowSource('keyboard')
        }}
      />
      <DndContext
        sensors={sensors}
        collisionDetection={closestCenter}
        modifiers={[restrictToVerticalAxis, restrictToParentElement]}
        onDragStart={handleDragStart}
        onDragMove={handleDragMove}
        onDragEnd={handleDragEnd}
      >
        <div ref={tableContainerRef}>
          {view === 'list' ? (
            <SortableContext items={rowIds} strategy={verticalListSortingStrategy}>
              <div>
                {rows.length ? (
                  rows.map((row, index) => {
                    const isSelected = row.getIsSelected()
                    const prevSelected = rows[index - 1]?.getIsSelected() ?? false
                    const nextSelected = rows[index + 1]?.getIsSelected() ?? false
                    return (
                      <ListRow
                        key={`${row.id}-${isSelected ? 1 : 0}-${prevSelected ? 1 : 0}-${nextSelected ? 1 : 0}`}
                        row={row}
                        displayIndex={index}
                        activeRowIndex={activeRowIndex}
                        activeRowSource={activeRowSource}
                        reorderable={!!onRowReorder}
                        customTranslateY={customTransforms ? customTransforms[index] : null}
                        isDragGroup={multiDragActive && row.getIsSelected()}
                        justDropped={justDropped}
                        onMeasureHeight={index === 0 ? (h) => { rowHeightRef.current = h } : undefined}
                        onRowClick={(i) => {
                          setActiveRowSource('mouse')
                          setActiveRowIndex(i)
                          row.toggleSelected()
                        }}
                        onRowMouseEnter={(i) => {
                          if (suppressMouseRef.current) return
                          setActiveRowSource('mouse')
                          setActiveRowIndex(i)
                        }}
                        onContextMenu={handleContextMenu}
                      />
                    )
                  })
                ) : (
                  <div className="h-24 flex items-center justify-center text-muted-foreground text-sm">
                    No results found.
                  </div>
                )}
              </div>
            </SortableContext>
          ) : (
            <Table className="border-separate border-spacing-0">
              <TableHeader>
                {table.getHeaderGroups().map((headerGroup) => (
                  <TableRow key={headerGroup.id} className="hover:bg-transparent">
                    {headerGroup.headers.map((header) => (
                      <TableHead
                        key={header.id}
                        style={header.column.columnDef.size ? { width: header.column.columnDef.size } : undefined}
                        className={cn(
                          'text-xs font-medium text-muted-foreground uppercase tracking-wide h-8',
                          (header.id === '_select' || header.id === '_reorder') && 'w-6 !pl-2 !pr-0',
                          header.column.getCanSort() && 'cursor-pointer select-none'
                        )}
                        onClick={
                          header.column.getCanSort()
                            ? header.column.getToggleSortingHandler()
                            : undefined
                        }
                      >
                        {header.isPlaceholder ? null : header.id === '_select' || header.id === '_reorder' ? (
                          flexRender(header.column.columnDef.header, header.getContext())
                        ) : (
                          <div className="flex items-center gap-1">
                            {flexRender(header.column.columnDef.header, header.getContext())}
                            {header.column.getCanSort() && (
                              <ArrowUpDownIcon
                                className={cn(
                                  'h-3 w-3 transition-opacity',
                                  header.column.getIsSorted()
                                    ? 'opacity-100 text-foreground'
                                    : 'opacity-30'
                                )}
                              />
                            )}
                          </div>
                        )}
                      </TableHead>
                    ))}
                  </TableRow>
                ))}
              </TableHeader>
              <SortableContext items={rowIds} strategy={verticalListSortingStrategy}>
                <TableBody>
                  {rows.length ? (
                    rows.map((row, index) => {
                      const isSelected = row.getIsSelected()
                      const prevSelected = rows[index - 1]?.getIsSelected() ?? false
                      const nextSelected = rows[index + 1]?.getIsSelected() ?? false
                      return <SortableRow
                        key={`${row.id}-${isSelected ? 1 : 0}-${prevSelected ? 1 : 0}-${nextSelected ? 1 : 0}`}
                        row={row}
                        displayIndex={index}
                        activeRowIndex={activeRowIndex}
                        activeRowSource={activeRowSource}
                        reorderable={!!onRowReorder}
                        customTranslateY={customTransforms ? customTransforms[index] : null}
                        isDragGroup={multiDragActive && row.getIsSelected()}
                        justDropped={justDropped}
                        onMeasureHeight={index === 0 ? (h) => { rowHeightRef.current = h } : undefined}
                        onRowClick={(i) => {
                          setActiveRowSource('mouse')
                          setActiveRowIndex(i)
                          row.toggleSelected()
                        }}
                        onRowMouseEnter={(i) => {
                          if (suppressMouseRef.current) return
                          setActiveRowSource('mouse')
                          setActiveRowIndex(i)
                        }}
                        onContextMenu={handleContextMenu}
                      />
                    })
                  ) : (
                    <TableRow>
                      <TableCell
                        colSpan={allColumns.length}
                        className="h-24 text-center text-muted-foreground text-sm"
                      >
                        No results found.
                      </TableCell>
                    </TableRow>
                  )}
                </TableBody>
              </SortableContext>
            </Table>
          )}
        </div>
      </DndContext>

      <TableFooter
        ref={paginationRef}
        rowCount={table.getFilteredRowModel().rows.length}
        showPagination={!showAll}
        pageIndex={pageIndex}
        pageCount={pageCount}
        canPreviousPage={table.getCanPreviousPage()}
        canNextPage={table.getCanNextPage()}
        onPreviousPage={() => table.previousPage()}
        onNextPage={() => table.nextPage()}
        onShiftTabToTable={() => {
          setActiveRowIndex(rows.length - 1)
          setActiveRowSource('keyboard')
          beforeSentinelRef.current?.focus()
        }}
      />

      <ContextMenu
        contextMenu={contextMenu}
        contextSub={contextSub}
        rowActions={rowActions ?? []}
        onSetContextSub={setContextSub}
        onClose={() => { setContextMenu(null); setContextSub(null) }}
        getContextRows={getContextRows}
      />

      <SelectionBar
        selectedCount={selectedCount}
        rowActions={rowActions}
        onClearSelection={() => table.resetRowSelection()}
        onOpenActions={() => setActionsOpen(true)}
      />

      {rowActions?.length ? (
        <ActionsDialog
          open={actionsOpen}
          onOpenChange={setActionsOpen}
          rowActions={rowActions}
          actionPage={actionPage}
          onSetActionPage={setActionPage}
          effectiveRows={effectiveRows}
          actionsHeading={actionsHeading}
        />
      ) : null}
    </div>
    </TooltipProvider>
  )
}

import type { Row, Table } from '@tanstack/react-table'
import * as React from 'react'
import type { RowAction } from './types'

interface UseKeyboardHandlerParams<TData> {
  rowActions?: RowAction<TData>[]
  rows: Row<TData>[]
  activeRowIndex: number | null
  selectedCount: number
  contextMenu: { x: number; y: number; rowIndex: number } | null
  table: Table<TData>
  effectiveRows: TData[]
  setActionsOpen: (open: boolean) => void
  setActionPage: (page: RowAction<TData> | null) => void
  setActiveRowIndex: React.Dispatch<React.SetStateAction<number | null>>
  setActiveRowSource: (source: 'keyboard' | 'mouse') => void
  suppressMouseRef: React.MutableRefObject<boolean>
  setContextMenu: (menu: null) => void
}

export function useKeyboardHandler<TData>({
  rowActions,
  rows,
  activeRowIndex,
  selectedCount,
  contextMenu,
  table,
  effectiveRows,
  setActionsOpen,
  setActionPage,
  setActiveRowIndex,
  setActiveRowSource,
  suppressMouseRef,
  setContextMenu,
}: UseKeyboardHandlerParams<TData>) {
  React.useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement
      if (
        target.tagName === 'INPUT' ||
        target.tagName === 'TEXTAREA' ||
        target.tagName === 'SELECT' ||
        target.isContentEditable
      ) return

      if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
        if (!rowActions?.length || !effectiveRows.length) return
        e.preventDefault()
        setActionsOpen(true)
      } else if ((e.metaKey || e.ctrlKey) && e.key === 'a') {
        e.preventDefault()
        table.toggleAllPageRowsSelected(true)
      } else if ((e.metaKey || e.ctrlKey) && e.key === 'ArrowUp') {
        e.preventDefault()
        suppressMouseRef.current = true
        setActiveRowSource('keyboard')
        setActiveRowIndex(0)
      } else if ((e.metaKey || e.ctrlKey) && e.key === 'ArrowDown') {
        e.preventDefault()
        suppressMouseRef.current = true
        setActiveRowSource('keyboard')
        setActiveRowIndex(rows.length - 1)
      } else if (e.key === 'Tab' && !e.shiftKey && activeRowIndex === rows.length - 1) {
        setActiveRowIndex(null)
      } else if (e.key === 'Tab' && e.shiftKey && activeRowIndex === 0) {
        setActiveRowIndex(null)
      } else if ((e.key === 'ArrowDown' && !e.altKey) || (e.key === 'Tab' && !e.shiftKey && activeRowIndex !== null && activeRowIndex !== rows.length - 1)) {
        e.preventDefault()
        suppressMouseRef.current = true
        setActiveRowSource('keyboard')
        setActiveRowIndex((prev) =>
          prev === null ? 0 : Math.min(prev + 1, rows.length - 1)
        )
      } else if ((e.key === 'ArrowUp' && !e.altKey) || (e.key === 'Tab' && e.shiftKey && activeRowIndex !== null && activeRowIndex !== 0)) {
        e.preventDefault()
        suppressMouseRef.current = true
        setActiveRowSource('keyboard')
        setActiveRowIndex((prev) =>
          prev === null ? 0 : Math.max(prev - 1, 0)
        )
      } else if ((e.key === ' ' || e.key === 'x') && activeRowIndex !== null) {
        e.preventDefault()
        rows[activeRowIndex]?.toggleSelected()
      } else if (e.key === 'Enter' && activeRowIndex !== null && rowActions?.length && effectiveRows.length) {
        e.preventDefault()
        setActionsOpen(true)
      } else if (e.key === 'Escape') {
        if (contextMenu) {
          setContextMenu(null)
        } else if (selectedCount > 0) {
          table.resetRowSelection()
        } else {
          setActiveRowIndex(null)
        }
      } else if (rowActions?.length) {
        const allSubActions = rowActions.flatMap((a) => a.subActions ?? [])
        const matchedSub = allSubActions.find(
          (a) =>
            a.shortcutKeys &&
            a.shortcutKeys.key === e.key &&
            !!a.shortcutKeys.altKey === e.altKey &&
            !!a.shortcutKeys.shiftKey === e.shiftKey &&
            !!a.shortcutKeys.metaKey === e.metaKey &&
            !!a.shortcutKeys.ctrlKey === e.ctrlKey,
        )
        if (matchedSub) {
          e.preventDefault()
          if (!effectiveRows.length) return
          suppressMouseRef.current = true
          matchedSub.onClick?.(effectiveRows)
        } else if (!e.metaKey && !e.ctrlKey && !e.altKey) {
          const matched = rowActions.find((a) => a.shortcut === e.key)
          if (matched) {
            e.preventDefault()
            if (!effectiveRows.length) return
            if (matched.subActions?.length) {
              setActionPage(matched)
              setActionsOpen(true)
            } else {
              matched.onClick?.(effectiveRows)
            }
          }
        }
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [rowActions, rows, activeRowIndex, selectedCount, contextMenu, table])
}
